cd /var/tmp/loop-bench/runs/bc0793e2e2af/workspace/target; cat > /tmp/reanchor.mjs <<'EOF'
import fs from 'fs';import path from 'path';
const root=process.cwd();
const walk=d=>fs.readdirSync(d,{withFileTypes:true}).flatMap(e=>e.isDirectory()?walk(path.join(d,e.name)):[path.join(d,e.name)]);
const files=[...walk('specs'),...(fs.existsSync('adrs')?walk('adrs'):[])].filter(f=>f.endsWith('.md'));
const cache={};
for(const f of files){
  let s=fs.readFileSync(f,'utf8');let ch=false;
  s=s.replace(/\[validated by:? ([^\]]+)\]\(([^)#]+\.test\.ts)#L(\d+)\)/g,(m,title,p,ln)=>{
    const tp=path.normalize(path.join(path.dirname(f),p));
    if(!fs.existsSync(tp))return m;
    const lines=(cache[tp]??=fs.readFileSync(tp,'utf8').split('\n'));
    const idx=lines.findIndex(l=>/^\s*(it|test)\(/.test(l)&&l.includes(title.replace(/'/g,"\\'"))||(/^\s*(it|test)\(/.test(l)&&l.includes(title)));
    if(idx<0){console.log('UNMAPPED',f,title);return m;}
    if(idx+1!=+ln)ch=true;
    return m.replace(/#L\d+\)$/,`#L${idx+1})`);
  });
  if(ch){fs.writeFileSync(f,s);console.log('updated',f);}
}
EOF
